```

```tsx
// Fix
type ListProps = {
  items?: string[] | null;
};

export function List({ items }: ListProps) {
  return (
    <ul>
      {(items ?? []).map((item) => (
        <li key={item}>{item}</li>
      ))}
    </ul>
  );
}
```

`items ?? []` handles both `undefined` and `null`. If `items` must always exist, remove `?` from `ListProps` and fix the caller to pass an array.
